cat > app/Http/Validators/LocaleValidator.ts <<'EOF'
import { z } from 'zod'

export const SUPPORTED_LOCALES = ['en', 'ja'] as const

export const LocalePayloadSchema = z.object({
  locale: z.enum(SUPPORTED_LOCALES),
})
EOF
cat > app/Http/Controllers/LocaleController.ts <<'EOF'
import { Controller } from '@guren/core'

const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365

export default class LocaleController extends Controller {
  async update(): Promise<Response> {
    const { locale } = this.validated('locale.update').body

    return this.redirect(this.backPath(), {
      status: 303,
      headers: { 'Set-Cookie': `locale=${locale}; Path=/; Max-Age=${ONE_YEAR_SECONDS}; SameSite=Lax` },
    })
  }

  // Only the path and query of the Referer are used, so a foreign Referer
  // cannot turn this into an open redirect.
  private backPath(): string {
    const referer = this.ctx.req.header('Referer')
    if (!referer) return '/'
    try {
      const url = new URL(referer, 'http://localhost')
      return `${url.pathname}${url.search}` || '/'
    } catch {
      return '/'
    }
  }
}
EOF
sed -i '' "s/supported: \['en'\]/supported: ['en', 'ja']/" src/app.ts
sed -i '' "s#^import { PostResource.*#&\nimport LocaleController from '../app/Http/Controllers/LocaleController.js'\nimport { LocalePayloadSchema } from '../app/Http/Validators/LocaleValidator.js'#" routes/web.ts
sed -i '' "s#^  registerAuthRoutes(router)#  router.post('/locale', { name: 'locale.update', body: LocalePayloadSchema }, [LocaleController, 'update'])\n\n&#" routes/web.ts
git diff routes src
